<template><div class="lesson-cover-control"><input ref="input" type="file" hidden accept="image/jpeg,image/png,image/webp" @change="upload($event.target.files[0]);$event.target.value=''"/><div class="cover-drop" @dragover.prevent @drop.prevent="upload($event.dataTransfer.files[0])"><img v-if="url" :src="url" alt="教案封面预览"/><div v-else class="cover-placeholder"><el-icon><Picture /></el-icon><span>资料封面</span></div><div class="cover-actions"><el-button :loading="loading" @click="input?.click()">{{modelValue?'更换封面':'上传封面'}}</el-button><el-button v-if="modelValue" link type="danger" :disabled="loading" @click="remove">移除</el-button><p>用于小程序首页与资料列表。建议 800 × 600，支持 JPG / PNG / WebP，最大 5MB。</p></div></div></div></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue'
import {ElMessage} from 'element-plus'
import {Picture} from '@element-plus/icons-vue'
import {knowledgeApi as api} from '@/api'
const props=defineProps({modelValue:{type:String,default:null}}),emit=defineEmits(['update:modelValue','busy']),input=ref(null),url=ref(''),loading=ref(false);let resource,sequence=0,loadedId
function clean(){if(resource)URL.revokeObjectURL(resource);resource=null;url.value=''}
watch(()=>props.modelValue,async id=>{if(id&&id===loadedId)return;const current=++sequence;clean();loadedId=id;if(!id)return;loading.value=true;emit('busy',true);try{let index=0,total=1,parts=[];do{const r=await api.chunk(id,index,0);if(current!==sequence)return;total=r.total;const raw=atob(r.chunk);parts.push(Uint8Array.from(raw,c=>c.charCodeAt(0)));index++}while(index<total);resource=URL.createObjectURL(new Blob(parts,{type:'image/jpeg'}));url.value=resource}catch(e){ElMessage.warning(e.message||'封面预览暂不可用')}finally{if(current===sequence){loading.value=false;emit('busy',false)}}},{immediate:true})
async function upload(file){if(!file||loading.value)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024||!file.size){ElMessage.warning('请上传5MB以内的JPG、PNG或WebP封面');return}loading.value=true;emit('busy',true);try{const r=await api.upload(file,()=>{});++sequence;loadedId=r.file.id;clean();resource=URL.createObjectURL(file);url.value=resource;emit('update:modelValue',r.file.id);ElMessage.success('封面已上传，保存并发布后生效')}catch(e){ElMessage.error(e.message)}finally{loading.value=false;emit('busy',false)}}
function remove(){if(loading.value)return;++sequence;loadedId=null;clean();emit('update:modelValue',null)}
onBeforeUnmount(()=>{sequence++;clean()})
</script>
<style scoped>.cover-drop{display:flex;align-items:center;gap:16px;padding:16px;border:1px solid #e4eaf3;background:#fafcfe;border-radius:10px}.cover-drop img,.cover-placeholder{width:128px;height:96px;object-fit:cover;flex-shrink:0;border-radius:8px}.cover-placeholder{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;background:#edf2fa;color:#91a4bf;font-size:11px}.cover-placeholder .el-icon{font-size:27px}.cover-actions p{margin:10px 0 0;font-size:11px;color:#91a0b4;line-height:1.7}.cover-actions{min-width:0}@media(max-width:600px){.cover-drop{align-items:flex-start}.cover-drop img,.cover-placeholder{width:96px;height:72px}}</style>
